Rules.InvariantScript:
Set(workerVar,{copyName:ThisItem.Name,base64Image:ThisItem.Value});
If(workerVar in RTEImages,Remove(RTEImages,LookUp(RTEImages, ThisItem.Value = base64Image)));
Remove(attItems,LookUp(attItems,ThisItem.Value = Value));
Remove(JointAttachments,ThisItem)

ForAll
(
    Self.Attachments As Attachment,
    If(Not(Attachment in JointAttachments),Collect(JointAttachments,{Name:Attachment.Name,Value:Attachment.Value}))
);
ClearCollect(attItems,Self.Attachments);
Reset(AddMediaAttachmentControl);

If( "<img" in CopyPasteRTE_46.HtmlText, Collect(RTEImages,{copyName:App.ActiveScreen.Name&" ScreenShot "&Text(Now(),DateTimeFormat.UTC), base64Image:CopyPasteRTE_46.HtmlText});Collect(JointAttachments,{Name:App.ActiveScreen.Name&" ScreenShot "&Text(Now(),DateTimeFormat.UTC), Value:CopyPasteRTE_42.HtmlText});
Reset(CopyPasteRTE_46);
, Notify("No Valid Image"));

ForAll(
    attItems As Attachment,
            AttachFiles.Run(
            AddMedia.ForSTITickID,
            {
                file:{
                    contentBytes: Attachment.Value,
                    name: Attachment.Name
                }
            }
        ) 
);
ForAll(
    RTEImages As RTEI,
    With({varHTMLTable: Split(RTEI.base64Image , "<img")}, If(CountRows(varHTMLTable)>1, With({varB64Start:Find("<img",RTEI.base64Image)+32},With({varB64End:Find("""",Mid(RTEI.base64Image,varB64Start))-1},CopyPasteTest.Run(Mid(RTEI.base64Image,varB64Start,varB64End),RTEI.copyName & Text(Now(),DateTimeFormat.UTC) &".png", AddMedia.ForSTITickID)
))))
        );
Clear(RTEImages);
Clear(JointAttachments);
Clear(attItems);
AddMedia.OpenMedia();
